# Generated by manage.py generate_test_cases.
"""Exercise generic endpoint memory independently of the SQL discovery endpoint."""

from datetime import timedelta
from types import SimpleNamespace
from typing import Any
from unittest.mock import patch
from uuid import uuid4

from django.core.exceptions import ValidationError
from django.http import HttpRequest
from django.utils import timezone

from bloomerp.agents.memory import conversation_memory_context, remember_tool_result
from bloomerp.mcp.definition import McpTool
from bloomerp.mcp.memory import McpMemoryPolicy, MemoryPayload, MemoryRecords
from bloomerp.models.agents import AIConversationMemory
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)

from ._fixtures import AgentModelFixtures


def extract_notes(result: MemoryPayload) -> MemoryRecords:
    """Extract notes from a non-SQL result format."""
    return result["notes"]


def merge_notes(previous: MemoryPayload, current: MemoryPayload) -> MemoryPayload:
    """Prefer new values while retaining earlier independent facts."""
    return {**previous, **current}


def validate_notes(request: HttpRequest, records: MemoryRecords) -> MemoryRecords:
    """Require an active owner for this fixture's endpoint policy."""
    return records if request.user.is_active else {}


POLICY = McpMemoryPolicy(
    extract=extract_notes,
    merge=merge_notes,
    validate=validate_notes,
    context_prefix="Resolved entities: ",
    ttl=timedelta(hours=1),
)


class TestAiconversationMemoryModel(AgentModelFixtures, BloomerpModelTestCase):
    """Test persistence, policy lifecycle and provenance with generated scenarios."""

    model = AIConversationMemory

    def get_test_scenarios(self) -> list[ModelScenario[AIConversationMemory]]:
        """Declare reusable memory and cross-conversation provenance scenarios."""
        return self.with_agent_fixtures(
            [
                ModelScenario(
                    name="Successful read memory survives interruption but unsafe sources do not",
                    create_args=self.memory_args,
                    create_validators=self.interrupted_read_memory_is_available,
                ),
                ModelScenario(
                    name="Generic hooks persist merge and replay without duplicates",
                    create_args=self.memory_args,
                    create_validators=self.generic_memory_works,
                ),
                ModelScenario(
                    name="Expiry versions and removed policies suppress context",
                    create_args=self.memory_args,
                    create_validators=self.lifecycle_is_enforced,
                ),
                ModelScenario(
                    name="Foreign source provenance is rejected",
                    create_args=self.foreign_memory_args,
                    expected_exceptions=[
                        ExpectedModelException(
                            phase="create", exception=ValidationError
                        )
                    ],
                ),
            ]
        )

    def memory_args(self) -> dict[str, Any]:
        """Create a completed source call and an initial memory record."""
        self.memory_run = self.make_run(status="completed")
        self.memory_tool = self.make_tool(
            self.memory_run,
            tool_identifier="fixture_lookup",
            status="completed",
            result={"notes": {"entity": {"id": 2, "label": "David's workspace"}}},
        )
        return {
            "conversation": self.conversation,
            "source_tool_call": self.memory_tool,
            "tool_identifier": "fixture_lookup",
            "key": "seed",
            "payload": {"seed": True},
        }

    def interrupted_read_memory_is_available(
        self, memory: AIConversationMemory
    ) -> bool:
        """Exercise actual endpoint metadata across cancelled, failed and interrupted runs."""
        contract = McpTool(memory=POLICY, read_only_hint=True)
        route = SimpleNamespace(url_name="fixture_lookup", mcp=contract)
        with patch("bloomerp.router.router.get_mcp_routes", return_value=[route]):
            for status in ("cancelled", "failed", "running"):
                self.memory_run.status = status
                self.memory_run.save()
                with self.subTest(run_status=status):
                    self.assertIn(
                        '"seed":true',
                        conversation_memory_context(
                            self.conversation, before_sequence=2
                        ),
                    )
                    self.assertIsNone(
                        conversation_memory_context(
                            self.conversation, before_sequence=1
                        )
                    )
                    self.assertIsNone(
                        conversation_memory_context(
                            self.other_conversation, before_sequence=2
                        )
                    )
                    for hint in (False, None):
                        contract.read_only_hint = hint
                        self.assertIsNone(
                            conversation_memory_context(
                                self.conversation, before_sequence=2
                            )
                        )
                    contract.read_only_hint = True
            for status in ("failed", "unknown", "cancelled", "running"):
                self.memory_tool.status = status
                self.memory_tool.save()
                with self.subTest(tool_status=status):
                    self.assertIsNone(
                        conversation_memory_context(
                            self.conversation, before_sequence=2
                        )
                    )
            self.memory_tool.status = "completed"
            self.memory_tool.save()
            self.conversation.owner.is_active = False
            self.assertIsNone(
                conversation_memory_context(self.conversation, before_sequence=2)
            )
        return True

    def foreign_memory_args(self) -> dict[str, Any]:
        """Point a memory at another conversation's source to exercise validation."""
        return {**self.memory_args(), "conversation": self.other_conversation}

    def generic_memory_works(self, memory: AIConversationMemory) -> bool:
        """Prove generic policies persist, merge, isolate, and serialize valid context."""
        with patch(
            "bloomerp.agents.memory.memory_policies",
            return_value={"fixture_lookup": POLICY},
        ):
            remember_tool_result(self.memory_tool)
            remember_tool_result(self.memory_tool)
            self.assertEqual(self.conversation.memories.count(), 2)
            note = self.conversation.memories.get(key="entity")
            self.assertIsNotNone(note.expires_at)
            newer = self.make_tool(
                self.memory_run,
                provider_call_id=str(uuid4()),
                tool_identifier="fixture_lookup",
                status="completed",
                result={"notes": {"entity": {"selected": True}}},
            )
            remember_tool_result(newer)
            remember_tool_result(self.memory_tool)
            note.refresh_from_db()
            self.assertEqual(
                note.payload, {"id": 2, "label": "David's workspace", "selected": True}
            )
            self.assertEqual(note.source_tool_call_id, newer.pk)
            self.assertEqual(self.conversation.memories.count(), 2)
            self.assertIn(
                "David's workspace",
                conversation_memory_context(self.conversation, before_sequence=2),
            )
            self.assertIsNone(
                conversation_memory_context(self.other_conversation, before_sequence=2)
            )
            self.assertIsNone(
                conversation_memory_context(self.conversation, before_sequence=1)
            )
            newer.status = "failed"
            remember_tool_result(newer)
            self.assertEqual(self.conversation.memories.count(), 2)
        return True

    def lifecycle_is_enforced(self, memory: AIConversationMemory) -> bool:
        """Do not inject expired, unsupported, unregistered or unvalidated notes."""
        with patch(
            "bloomerp.agents.memory.memory_policies",
            return_value={"fixture_lookup": POLICY},
        ):
            memory.expires_at = timezone.now() - timedelta(seconds=1)
            memory.save()
            self.assertIsNone(
                conversation_memory_context(self.conversation, before_sequence=2)
            )
            memory.expires_at = None
            memory.version = 2
            memory.save()
            self.assertIsNone(
                conversation_memory_context(self.conversation, before_sequence=2)
            )
            memory.version = 1
            memory.save()
            self.conversation.owner.is_active = False
            self.assertIsNone(
                conversation_memory_context(self.conversation, before_sequence=2)
            )
        with patch("bloomerp.agents.memory.memory_policies", return_value={}):
            self.assertIsNone(
                conversation_memory_context(self.conversation, before_sequence=2)
            )
        return True
